const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '比例尺 1:25000' },
      { kind: 'text', payload: '图上距离 6 厘米' },
      { kind: 'text', payload: '实际距离 150000 厘米' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: '5' },
      { kind: 'text', payload: '6' },
      { kind: 'text', payload: '厘米' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = Math.round(W * 0.10);
    var x1 = Math.round(W * 0.90);
    var y = Math.round(H * 0.52);
    var tickHalf = Math.max(8, Math.round(H * 0.03));
    var N = 6;
    var seg = (x1 - x0) / N;
    var paths = [];
    paths.push({ id: 'line', commands: visualSdk.polyline([[x0, y], [x1, y]]) });
    var tickCmds = [];
    for (var i = 0; i <= N; i++) {
      var x = x0 + seg * i;
      var cmds = visualSdk.polyline([[x, y - tickHalf], [x, y + tickHalf]]);
      for (var j = 0; j < cmds.length; j++) tickCmds.push(cmds[j]);
    }
    paths.push({ id: 'ticks', commands: tickCmds });
    function widthOf(idx, fallback) {
      var m = metrics && metrics[idx];
      if (m && typeof m.width === 'number' && isFinite(m.width)) return m.width;
      if (m && m.bounds && typeof m.bounds.width === 'number') return m.bounds.width;
      return fallback;
    }
    var children = [];
    children.push({ type: 'path', pathId: 'line', stroke: '#26354a' });
    children.push({ type: 'path', pathId: 'ticks', stroke: '#26354a' });
    var tickLabelY = y + tickHalf + 22;
    for (var k = 0; k <= N; k++) {
      var lx = x0 + seg * k;
      var label = String(k);
      var w = widthOf(3 + k, 8);
      children.push({ type: 'label', text: label, x: lx - w / 2, y: tickLabelY, fontSize: 14, fill: '#26354a' });
    }
    children.push({ type: 'label', text: '厘米', x: x1 + 14, y: tickLabelY, fontSize: 14, fill: '#26354a' });
    children.push({ type: 'label', text: '比例尺 1:25000', x: x0, y: Math.max(24, y - tickHalf - 64), fontSize: 16, fill: '#26354a' });
    children.push({ type: 'label', text: '图上距离 6 厘米', x: x0, y: Math.max(48, y - tickHalf - 38), fontSize: 15, fill: '#26354a' });
    children.push({ type: 'label', text: '实际距离 150000 厘米', x: x0, y: tickLabelY + 36, fontSize: 16, fill: '#26354a' });
    return {
      schemaVersion: 1,
      sceneId: 'scale-distance-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
